{
  "technical_and_design_decisions": [
    "U1: Use ZooKeeper chroot path per tenant for namespace isolation.",
    "U2: Use Java Console.readPassword() for interactive password input to avoid logging.",
    "U3: Create a git branch for maintenance releases and update Maven version.",
    "U4: Remove deprecated functions and update all references; no backward compatibility needed.",
    "U5: Use ZooKeeper to store admin server random port; shell reads from ZK.",
    "U6: Update test suites to use new Kafka consumer API (0.9 rewrite).",
    "U7: Implement Motion-JPEG using JavaCV (OpenCV wrapper) despite platform issues; fallback to alternative if needed.",
    "U8: Add 'messageRatesEnabled' property in servers.yml and use in cluster view rendering."
  ],
  "assumptions": [
    "Existing codebase is Spring XD (or similar) with ZooKeeper, Tomcat, Kafka, etc.",
    "Development environment is standard Java 17+ with Maven/Gradle.",
    "All user stories are part of the same software increment and must be implemented.",
    "Spikes for U5 and U7 include research time; effort estimates include that.",
    "U6 assumes the Kafka upgrade is already applied but tests are failing; we fix the tests.",
    "U3 is a process change involving branch creation and CI config adjustment.",
    "All estimates are in work-hours for a single developer.",
    "No external dependencies beyond existing libraries.",
    "Testing includes unit and integration tests as appropriate."
  ],
  "activities": [
    {
      "activity_id": "U1-Design",
      "activity_name": "Design namespace isolation",
      "activity_description": "Design approach for isolating ZK metadata per tenant using ZooKeeper chroot or prefix paths.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "U1-Impl",
      "activity_name": "Implement namespace isolation",
      "activity_description": "Implement changes to ZK client code to support tenant-specific namespaces.",
      "most_likely_effort": 9
    },
    {
      "activity_id": "U1-Test",
      "activity_name": "Test namespace isolation",
      "activity_description": "Write unit and integration tests for namespace isolation.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "U2-Design",
      "activity_name": "Design interactive login",
      "activity_description": "Design interactive credential input mechanism for Admin server access.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U2-Impl",
      "activity_name": "Implement interactive login",
      "activity_description": "Implement credential prompt, pass to server, avoid logging.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "U2-Test",
      "activity_name": "Test interactive login",
      "activity_description": "Write tests for the login flow.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "U3-Setup",
      "activity_name": "Setup maintenance branch",
      "activity_description": "Create maintenance branch from master, adjust versioning and CI configuration for minor releases.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "U4-Analysis",
      "activity_name": "Analyze deprecated code",
      "activity_description": "Identify deprecated functions in module registry, Shell, and Admin-UI modules.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "U4-Removal",
      "activity_name": "Remove deprecated code",
      "activity_description": "Remove deprecated functions and update all references.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "U4-Test",
      "activity_name": "Test cleanup",
      "activity_description": "Update and run tests to verify no side effects from removal.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "U5-Research",
      "activity_name": "Research port discovery approach",
      "activity_description": "Research whether to use ZK for storing admin server random port or other approach.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "U5-Impl",
      "activity_name": "Implement port discovery",
      "activity_description": "Implement in xd-shell the ability to retrieve admin server port from ZooKeeper.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "U5-Test",
      "activity_name": "Test port discovery",
      "activity_description": "Write tests for the discovery mechanism.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "U6-Analysis",
      "activity_name": "Analyze failing tests",
      "activity_description": "Identify tests failing after Kafka consumer upgrade and root cause.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "U6-Fix",
      "activity_name": "Fix failing tests",
      "activity_description": "Update test code to work with new Kafka consumer API (0.9 rewrite).",
      "most_likely_effort": 10
    },
    {
      "activity_id": "U6-Verify",
      "activity_name": "Verify test fixes",
      "activity_description": "Run tests and ensure all pass.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U7-Research",
      "activity_name": "Research Motion-JPEG feasibility",
      "activity_description": "Research Motion-JPEG format and implementation options for streaming ingest.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "U7-Design",
      "activity_name": "Design Motion-JPEG integration",
      "activity_description": "Design how to integrate Motion-JPEG with existing streaming infrastructure.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "U7-Impl",
      "activity_name": "Implement Motion-JPEG support",
      "activity_description": "Implement encoder/decoder for Motion-JPEG and integrate with stream processing.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "U7-Test",
      "activity_name": "Test Motion-JPEG and facial detection",
      "activity_description": "Write tests for Motion-JPEG streaming and facial detection integration.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "U8-Design",
      "activity_name": "Design config parameter",
      "activity_description": "Define config property for enabling/disabling message rates in cluster view.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U8-Impl",
      "activity_name": "Implement config parameter",
      "activity_description": "Add YAML parsing for the new parameter and integrate into cluster view logic.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "U8-Test",
      "activity_name": "Test config parameter",
      "activity_description": "Write tests for the new config option.",
      "most_likely_effort": 4
    }
  ],
  "reported_total": {
    "most_likely_effort": 134
  }
}

